#!/usr/bin/env python3
"""
Round 107b (culprits), 28 September 2026. Needs round 106b.

The AI's pick of the countries most at threat, the Pastoral Land Commission's
case tables, INPE's 2023 fires, Land of Resistance's dates of birth and photos.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = "## Round 107b (28 September)\n\nNeeds round 106b. Tiles patches round107b_tiles.py and round107c_tiles.py beside it.\n\n- ai_threat_overall/destruction/suppression/crime: country rows under Where the\n  threat is greatest, from tiles threat/ai.json (scripts/ai_threat.py, Google\n  Gemini free tier, needs repo secret GEMINI_API_KEY passed as env in\n  refresh.yml's Run step; picks 20 per category with reasons; numbers checked).\n- Pastoral Land Commission tables: attacks_cpt_areas, attacks_cpt_land,\n  attacks_cpt_water, attacks_cpt_overexploitation (Of individuals > Of humans),\n  attacks_cpt_slave_cases (Slavery > Cases and enforcement).\n- inpe_fire_2023 (pmtiles, fine) under Destruction > Fire, built by tiles\n  scripts/inpe_fire.py from attacks/inpe_fire_foci_2023.geojson.gz.\n- Land of Resistance keeps dates of birth and photo links (owner's word).\n- Script version app.js?v=998.\n\n"
HEAD = "## Round 107b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round107b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 106b" not in text:
        sys.exit("round107b: round 106b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round107b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round107b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round107b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 106b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
